async function token() {
	const s = await validSession();
	if (!s) throw new Error("auth");
	return s.access_token;
}
async function nxGet(op, params = {}) {
	const q = new URLSearchParams({ op });
	for (const [k, v] of Object.entries(params)) if (v !== void 0 && v !== "") q.set(k, String(v));
	const res = await fetch(`/api/admin?${q}`, {
		headers: { Authorization: `Bearer ${await token()}` },
		credentials: "same-origin"
	});
	const data = await res.json().catch(() => ({}));
	if (!res.ok) throw new Error(res.status === 401 ? "auth" : data.error || String(res.status));
	return data;
}
async function nxPost(op, body) {
	const res = await fetch(`/api/admin?op=${op}`, {
		method: "POST",
		credentials: "same-origin",
		headers: {
			"Content-Type": "application/json",
			"x-nxs": "1",
			Authorization: `Bearer ${await token()}`
		},
		body: JSON.stringify(body ?? {})
	});
	const data = await res.json().catch(() => ({}));
	if (!res.ok) throw new Error(res.status === 401 ? "auth" : data.error || String(res.status));
	return data;
}
