function computeAlerts(t, ov, apps, rows) {
	const out = [];
	const h = ov.data?.health;
	if (h && !h.supabase) out.push({
		key: "sb",
		text: t("a_supabase"),
		go: "settings"
	});
	if (ov.hitsChecked && !ov.hits) out.push({
		key: "hits",
		text: t("a_hits"),
		go: "settings"
	});
	if (h && !h.github) out.push({
		key: "gh",
		text: t("a_github"),
		go: "settings"
	});
	if (apps && rows) for (const app of appList(apps)) {
		if (app.status === "ready" && app.visible && !rows.some((r) => r.slug === app.slug && r.body.trim()) && !["nibras-pdf", "nibras-arabic"].includes(app.slug)) out.push({
			key: `p-${app.slug}`,
			text: t("a_noprivacy", { name: app.name }),
			go: "pages",
			sub: "privacy"
		});
		if (app.status === "ready" && app.visible && !STORE_FIELDS.some(([k]) => app[k]?.trim())) out.push({
			key: `s-${app.slug}`,
			text: t("a_nostore", { name: app.name }),
			go: "apps"
		});
	}
	return out;
}
