function useLoad(load) {
	const [data, setData] = useState(null);
	const [error, setError] = useState("");
	const [busy, setBusy] = useState(false);
	const ref = useRef(load);
	ref.current = load;
	const run = useCallback((fresh = false) => {
		setBusy(true);
		setError("");
		ref.current(fresh).then(setData).catch((e) => setError(e instanceof Error ? e.message : "error")).finally(() => setBusy(false));
	}, []);
	useEffect(() => run(false), [run]);
	return {
		data,
		error,
		busy,
		run,
		setData
	};
}
